83|const B64URL = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
84|
85|export function newUploadId(): string {
86|  const bytes = new Uint8Array(16);
87|  globalThis.crypto.getRandomValues(bytes);
88|  let out = "u-";
89|  let bits = 0;
90|  let value = 0;
91|  for (const byte of bytes) {
92|    value = (value << 8) | byte;
93|    bits += 8;
94|    while (bits >= 6) {
95|      bits -= 6;
96|      out += B64URL[(value >> bits) & 63];
97|    }
98|  }
99|  if (bits > 0) out += B64URL[(value << (6 - bits)) & 63];
100|  return out;
