43|  book?: StyleBook;
44|}
45|
46|export interface OrchestrateDeps {
47|  kv: KV;
48|  store: ImageStore;
49|  generate: ImageGenerator;
50|  env: ImageEnv;
51|  content: ImageContent;
52|  ip: string;
53|  anonId: string;
54|  day: string;
55|  token?: string;
56|  // Scene holding the selection start; "" skips range reuse.
57|  sceneId: string;
58|  // Human gate, checked once on the cache-miss path after the lock.
59|  // Absent in tests that do not cover the check.
60|  human?: HumanCheckInput;
61|  // Receives the issued human cookie, if any; the handler sets it.
62|  humanOut?: { setCookie?: string };
63|}
64|
65|// One pass, no skipped steps: KV hit -> lock -> human -> Blob backfill ->
66|// quota -> budget -> generate -> store -> index -> release. Every failure
67|// after the reserve refunds quota, budget, and the daily counter and
68|// releases the lock.
69|export async function orchestrate(
70|  req: ImageRequest,
71|  deps: OrchestrateDeps,
72|): Promise<ImageResponse> {
73|  const key = imageKey(req);
74|  const indexKey = indexKeyFor(key);
75|  const lockKey = lockKeyFor(key);
