77|  // Passage range reuse: an overlapping cached selection serves this one.
78|  // Scene requests and unknown scenes skip all of it.
79|  let want: ParaRange | null = null;
80|  let rangesAt = "";
81|  let rangeList: ParaRange[] = [];
82|  if (req.kind === "passage" && deps.sceneId !== "") {
83|    want = { start: req.n, end: req.endN ?? req.n };
84|    rangesAt = rangeListKeyFor(req, deps.sceneId);
85|    rangeList = parseRanges(await deps.kv.get(rangesAt));
86|  }
87|  // shortcut: GET+SET can drop a concurrent append, which only costs a future reuse; upgrade to a Redis list if that matters.
88|  const recordRange = async (): Promise<void> => {
89|    const self = want;
90|    if (!self || rangeList.some((r) => r.start === self.start && r.end === self.end)) return;
91|    try {
92|      await deps.kv.set(rangesAt, JSON.stringify(addRange(rangeList, self)));
93|    } catch {
94|      console.error("image range index failed");
95|    }
96|  };
97|
98|  const indexed = await deps.kv.get(indexKey);
99|  if (indexed) {
100|    // Pictures cached before range reuse join the list on their next hit.
101|    await recordRange();
102|    return { status: "ready", url: indexed, cached: true, caption: captionFor(req, deps.content) };
103|  }
104|
105|  // Reusable range resolved now for the free KV hit; its Blob fallback
106|  // runs after the human check so probes cannot burn Blob list().
107|  let bestPath = "";
108|  let bestIndex = "";
109|  if (req.kind === "passage" && want) {
110|    const self = want;
111|    const best = pickReusable(
112|      rangeList.filter((r) => r.start !== self.start || r.end !== self.end),
113|      self,
114|    );
