116|      bestPath = imageKey({ ...req, n: best.start, endN: best.end });
117|      bestIndex = indexKeyFor(bestPath);
118|      const hit = await deps.kv.get(bestIndex);
119|      if (hit) {
120|        return { status: "ready", url: hit, cached: true, caption: captionFor(req, deps.content) };
121|      }
122|    }
123|  }
124|
125|  const token = deps.token ?? randomUUID();
126|  if (!(await deps.kv.setNxEx(lockKey, token, LOCK_TTL_SEC))) return { status: "pending" };
127|
128|  // Best-effort unlock: a release failure must never turn into a client 500.
129|  const release = async (): Promise<void> => {
130|    try {
131|      await deps.kv.releaseIfToken(lockKey, token);
132|    } catch {
133|      // Lock expires on its own; nothing to do.
134|    }
135|  };
136|
137|  const keys = quotaKeys({
138|    day: deps.day,
139|    ipHash: hashIp(ipBucket(deps.ip, deps.anonId), deps.env.ipSalt),
140|    anonId: deps.anonId,
141|  });
142|  let quotaTaken = false;
143|  let reservation: SpendReservation | null = null;
144|  // Best-effort refunds that clear their flag only after the write lands,
145|  // so the outer catch refunds each reserve exactly once.
146|  const refundQuotaOnce = async (): Promise<void> => {
147|    if (quotaTaken) {
148|      await refundDualQuota(deps.kv, keys);
149|      quotaTaken = false;
150|    }
151|  };
152|  const releaseSpendOnce = async (): Promise<void> => {
153|    await reservation?.release();
154|    reservation = null;
155|  };
156|
157|  try {
158|    if (deps.human) {
159|      const human = await checkHuman(deps.human);
