173|          await deps.kv.set(bestIndex, hit);
174|        } catch {
175|          console.error("image index failed");
176|        }
177|        await release();
178|        return { status: "ready", url: hit, cached: true, caption: captionFor(req, deps.content) };
179|      }
180|    }
181|    const existing = await deps.store.findUrl(key);
182|    if (existing) {
183|      try {
184|        await deps.kv.set(indexKey, existing);
185|      } catch {
186|        console.error("image index failed");
187|      }
188|      await recordRange();
189|      await release();
190|      return { status: "ready", url: existing, cached: true, caption: captionFor(req, deps.content) };
191|    }
192|
193|    const quota = await takeDualQuota(deps.kv, keys, {
194|      limit: DAILY_IMAGE_LIMIT,
195|      ttlSec: QUOTA_TTL_SEC,
196|    });
197|    if (!quota.ok) {
198|      await release();
199|      return { status: "error", code: "quota", message: MSG_QUOTA };
200|    }
201|    quotaTaken = true;
202|
203|    // Both caps apply only to requests paid with our key. The future
204|    // BYOK path must skip these reserves and check its own key instead.
205|    const spent = await reserveSpend(deps.kv, {
206|      amountMicro: imageCostMicro(),
207|      day: deps.day,
208|      spendCapMicro: deps.env.spendCapMicro,
209|      dailySpendCapMicro: deps.env.dailySpendCapMicro,
210|    });
211|    if (!spent.ok) {
212|      await releaseSpendOnce();
213|      await refundQuotaOnce();
214|      await release();
215|      return spent.which === "total"
216|        ? { status: "error", code: "budget", message: MSG_CREDITS_OUT }
217|        : { status: "error", code: "daily_budget", message: MSG_CREDITS_OUT };
218|    }
219|    reservation = spent.reservation;
220|
221|    let bytes: Uint8Array;
222|    try {
223|      bytes = await deps.generate.generate(
224|        buildFinalPrompt({
225|          kind: req.kind,
226|          passageText: deps.content.passageText,
227|          sceneTitle: deps.content.sceneTitle,
228|          sceneClip: deps.content.sceneClip,
229|          chapterPanels: deps.content.chapterPanels,
230|          style: req.style,
231|          book: deps.content.book,
232|          reference: deps.content.reference,
233|        }),
234|      );
235|    } catch (e) {
236|      await releaseSpendOnce();
237|      await refundQuotaOnce();
238|      await release();
