240|      return { status: "error", code: "unavailable", message: MSG_FAILED };
241|    }
242|
243|    try {
244|      const url = await deps.store.save(key, bytes);
245|      try {
246|        await deps.kv.set(indexKey, url);
247|      } catch {
248|        console.error("image index failed");
249|        await recordRange();
250|        await release();
251|        return { status: "ready", url, cached: false, caption: captionFor(req, deps.content) };
252|      }
253|      await recordRange();
254|      await release();
255|      return { status: "ready", url, cached: false, caption: captionFor(req, deps.content) };
256|    } catch (e) {
257|      // A lost save race leaves the winner's file behind; backfill from it.
258|      const raced = await deps.store.findUrl(key);
259|      if (raced) {
260|        try {
261|          await deps.kv.set(indexKey, raced);
262|        } catch {
263|          console.error("image index failed");
264|        }
265|        await recordRange();
266|        await release();
267|        return { status: "ready", url: raced, cached: true, caption: captionFor(req, deps.content) };
268|      }
269|      await releaseSpendOnce();
270|      await refundQuotaOnce();
271|      await release();
272|      console.error(`image store failed: ${errorTag(e)}`);
273|      return { status: "error", code: "unavailable", message: MSG_FAILED };
274|    }
275|  } catch (e) {
276|    await releaseSpendOnce();
277|    await refundQuotaOnce();
278|    await release();
279|    console.error(`image request failed: ${errorTag(e)}`);
280|    return { status: "error", code: "unavailable", message: MSG_FAILED };
281|  }
282|}
283|
284|function captionFor(req: ImageRequest, content: ImageContent): string {
285|  return buildCaption({
286|    kind: req.kind,
287|    sceneTitle: content.sceneTitle,
288|    passageText: content.passageText,
289|  });
