1|// One comic page per chapter, requested in the reader's style. Session
2|// cache per chapter and style, so reopening never refetches.
3|"use client";
4|
5|import { useCallback, useEffect, useRef, useState } from "react";
6|import { MSG_FAILED, MSG_HUMAN } from "@/core/images";
7|import { requestStyleFields } from "../image-style";
8|import type { ImageStylePref } from "../image-style";
9|import { HumanNeeded, ImageRequestError, isQuotaCode, poll } from "./image-poll";
10|
11|export type ChapterPage =
12|  | { phase: "loading" }
13|  | { phase: "ready"; url: string; caption: string }
14|  | { phase: "error"; message: string; quota?: boolean };
15|
16|const chapterCache = new Map<string, { url: string; caption: string }>();
17|
18|function cacheKey(ch: number, pref: ImageStylePref): string {
19|  return `${ch}::${JSON.stringify(requestStyleFields(pref))}`;
20|}
21|
22|function pageBody(
23|  bookId: string,
24|  textVersion: string,
25|  ch: number,
26|  pref: ImageStylePref,
27|  reachedCh: number,
28|): Record<string, unknown> {
29|  return { kind: "chapter", bookId, textVersion, ch, reachedCh, ...requestStyleFields(pref) };
30|}
31|
32|export function useChapterPage({
33|  bookId,
34|  textVersion,
35|  ch,
36|  pref,
37|  reachedCh,
38|}: {
39|  bookId: string;
40|  textVersion: string;
41|  ch: number;
42|  pref: ImageStylePref;
43|  reachedCh: number;
44|}): { page: ChapterPage; retry: () => void; needHuman: boolean; submitHumanPass: (pass: string) => void } {
45|  const reached = ch <= reachedCh;
46|  // The style pref arrives as a fresh object each render and is read
47|  // through a ref, like use-pictures; the key string tracks its value.
48|  const prefRef = useRef(pref);
49|  // eslint-disable-next-line react-hooks/refs -- latest-pref mirror; the key string tracks its value
50|  prefRef.current = pref;
51|  const key = cacheKey(ch, pref);
52|  const [page, setPage] = useState<ChapterPage>(() => {
53|    const hit = chapterCache.get(key);
54|    return hit ? { phase: "ready", url: hit.url, caption: hit.caption } : { phase: "loading" };
55|  });
56|  const [attempt, setAttempt] = useState(0);
57|  const [needHuman, setNeedHuman] = useState(false);
58|  const humanRetry = useRef<((pass: string) => void) | null>(null);
59|
60|  const request = useCallback(
61|    (pass?: string) => {
62|      setPage({ phase: "loading" });
63|      let cancelled = false;
64|      const stop = () => {
65|        cancelled = true;
66|      };
67|      void poll(pageBody(bookId, textVersion, ch, prefRef.current, reachedCh), pass)
68|        .then(({ url, caption }) => {
69|          chapterCache.set(key, { url, caption });
70|          if (!cancelled) setPage({ phase: "ready", url, caption });
71|        })
72|        .catch((err: unknown) => {
73|          if (cancelled) return;
74|          if (err instanceof HumanNeeded) {
75|            // eslint-disable-next-line react-hooks/immutability -- deferred human-retry callback, runs after render
76|            humanRetry.current = (next: string) => request(next);
77|            setNeedHuman(true);
78|            setPage({ phase: "error", message: MSG_HUMAN });
79|          } else {
80|            setPage({
81|              phase: "error",
82|              message: err instanceof Error ? err.message : MSG_FAILED,
83|              quota: err instanceof ImageRequestError && isQuotaCode(err.code),
84|            });
85|          }
86|        });
87|      return stop;
88|    },
89|    [bookId, textVersion, ch, key, reachedCh],
90|  );
91|
92|  // The widget proof retries the failed request once, with the proof on
93|  // the first post only; later polls reuse the issued cookie.
94|  const submitHumanPass = useCallback((pass: string) => {
95|    const retry = humanRetry.current;
96|    humanRetry.current = null;
97|    setNeedHuman(false);
98|    if (retry) retry(pass);
99|    else request(pass);
100|  }, [request]);
101|
102|  useEffect(() => {
103|    if (!reached) return;
104|    const hit = chapterCache.get(key);
105|    if (hit) {
106|      // eslint-disable-next-line react-hooks/set-state-in-effect -- cache-hit sync on chapter/pref change
107|      setPage({ phase: "ready", url: hit.url, caption: hit.caption });
108|      return;
109|    }
110|    const stop = request();
111|    return stop;
112|  }, [bookId, textVersion, ch, key, reached, reachedCh, attempt, request]);
113|
114|  const retry = useCallback(() => setAttempt((n) => n + 1), []);
115|  return { page, retry, needHuman, submitHumanPass };
