1|import "server-only";
2|import type { ImageGenerator } from "@/core/images";
3|
4|const ENDPOINT = "https://api.meta.ai/v1/images/generations";
5|
6|// A failed generation carrying only safe fields: the HTTP status and the
7|// provider's error code/type plus a short scrubbed message. Never the
8|// request, headers, or the raw body.
9|export class MetaImageError extends Error {
10|  constructor(
11|    readonly status: number,
12|    readonly detail: string,
13|  ) {
14|    super(`meta status ${status}${detail ? ` ${detail}` : ""}`);
15|    this.name = "MetaImageError";
16|  }
17|}
18|
19|const SECRETISH = /(bearer\s+\S+|sk-[\w-]+|[A-Za-z0-9_-]{32,})/gi;
20|
21|export function scrubDetail(text: string): string {
22|  return text.replace(SECRETISH, "[redacted]").replace(/\s+/g, " ").trim().slice(0, 160);
23|}
24|
25|async function safeErrorDetail(res: Response): Promise<string> {
26|  try {
27|    const json = (await res.json()) as { error?: { code?: unknown; type?: unknown; message?: unknown } };
28|    const err = json.error ?? {};
29|    const parts: string[] = [];
30|    if (typeof err.code === "string") parts.push(`code=${scrubDetail(err.code)}`);
31|    if (typeof err.type === "string") parts.push(`type=${scrubDetail(err.type)}`);
32|    if (typeof err.message === "string") parts.push(`"${scrubDetail(err.message)}"`);
33|    return parts.join(" ");
34|  } catch {
35|    return "";
36|  }
37|}
38|
39|// Providers word content filtering differently (content_policy_violation,
40|// safety_block, content_filter, "blocked"), so match a small marker set
41|// case-insensitively against the scrubbed code/type/message.
42|const POLICY_MARKERS = /content_policy|policy|safety|content_filter|blocked/i;
43|
44|export function isPolicyRejection(e: unknown): boolean {
45|  return e instanceof MetaImageError && POLICY_MARKERS.test(e.detail);
46|}
47|
48|// One-line reason for logs in operator scripts. Unknown errors map to
49|// their name only, so nothing unexpected is echoed.
50|export function safeFailureReason(e: unknown): string {
51|  if (e instanceof MetaImageError) return e.message;
52|  if (e instanceof Error && e.message === "meta empty image") return "meta empty image (likely filtered)";
53|  if (e instanceof Error && (e.name === "TimeoutError" || e.name === "AbortError")) return "timeout";
54|  return e instanceof Error ? e.name : "unknown error";
55|}
56|
57|// Meta image client. Reads no env: the caller passes the key in, and
58|// tests inject a fake generator instead of this module. The 100 s budget
59|// leaves room inside the 120 s route for Blob, quota, and the refund.
60|export function createMetaClient(apiKey: string): ImageGenerator {
61|  return {
62|    async generate(prompt: string): Promise<Uint8Array> {
63|      const res = await fetch(ENDPOINT, {
64|        method: "POST",
65|        headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
66|        body: JSON.stringify({
67|          model: "muse-image-1.0",
68|          prompt,
69|          n: 1,
70|          size: "1024x1024",
71|          output_format: "webp",
72|          response_format: "b64_json",
73|        }),
74|        signal: AbortSignal.timeout(100_000),
75|      });
76|      if (!res.ok) throw new MetaImageError(res.status, await safeErrorDetail(res));
77|      const json = (await res.json()) as { data?: Array<{ b64_json?: string }> };
78|      const b64 = json.data?.[0]?.b64_json;
79|      if (!b64) throw new Error("meta empty image");
80|      return new Uint8Array(Buffer.from(b64, "base64"));
81|    },
82|  };
83|}

